data.css:
/* Rainy Café — soft ceramic panels beside a rainy window.
Shape: containers 14px; fields/buttons 8px; tags capsule; avatars retain native shape.
Borders: 1px solid theme border. Shadows: soft blur only.
Selection: tinted fill; focus: inset ring. No motion or control relocation. */
:root {
 --mari-tokens-version: 1; --radius: 0.875rem;
 --mari-font-ui: system-ui, sans-serif; --mari-font-heading: Georgia, serif; --mari-font-chat: system-ui, sans-serif;
 --mari-selected-tint: var(--primary);
 --mari-app-backdrop: radial-gradient(ellipse at top right, #9b7049, #302720 75%);
 --mari-app-backdrop-position: center; --mari-app-backdrop-size: cover;
 --mari-page-veil: color-mix(in srgb, var(--background) 96%, transparent);
 --mari-top-bar-plate: var(--card); --mari-top-bar-plate-radius: 8px;
 --ov-text: var(--foreground); --ov-muted: var(--muted-foreground); --ov-dim: var(--muted-foreground); --ov-line: var(--border); --ov-accent: var(--primary); --ov-hover: var(--accent); --ov-active-bg: var(--secondary);
 --background: #241e1a; --foreground: #f5e9d9; --card: #302721; --card-foreground: #f5e9d9; --popover: #302721; --popover-foreground: #f5e9d9;
 --primary: #edbc7e; --primary-foreground: #2b1c0e; --secondary: #49392d; --secondary-foreground: #f5e9d9; --muted: #3b3028; --muted-foreground: #d0beaa; --accent: #514032; --accent-foreground: #fff1df;
 --border: #7d6855; --input: #8e755e; --ring: #edbc7e; --sidebar: #29221d; --sidebar-foreground: #f5e9d9; --sidebar-border: #7d6855; --sidebar-accent: #49392d; --sidebar-accent-foreground: #fff1df; --destructive: #f5a49a; --destructive-foreground: #381512;
}
[data-theme="light"] {
 --background: #f4ebdc; --foreground: #35271f; --card: #fff8ed; --card-foreground: #35271f; --popover: #fff8ed; --popover-foreground: #35271f;
 --primary: #854820; --primary-foreground: #fff8ed; --secondary: #ead8bf; --secondary-foreground: #35271f; --muted: #eee1cf; --muted-foreground: #705a47; --accent: #e8d3b6; --accent-foreground: #35271f;
 --border: #ac9072; --input: #9c7b5e; --ring: #854820; --sidebar: #f5e9d7; --sidebar-foreground: #35271f; --sidebar-border: #ac9072; --sidebar-accent: #ead8bf; --sidebar-accent-foreground: #35271f; --destructive: #a43129; --destructive-foreground: #fff8ed;
}
[data-theme="dark"] { color-scheme: dark; }
[data-mari-part="page"], [data-mari-part="home-widget"], .mari-window, .mari-drawer {
 background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); border-radius: 14px; box-shadow: 0 5px 20px -10px #160d0866;
}
[data-mari-part="message"], [data-mari-part="composer"] {
 background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); border-radius: 14px; box-shadow: 0 5px 20px -10px #160d0866;
}
[data-mari-part="top-bar"] { background: var(--sidebar); color: var(--sidebar-foreground); border-bottom: 1px solid var(--border); }
:where(button, input, textarea, select) { border-radius: 8px; }
:where(input, textarea, select) { background-color: var(--card); color: var(--foreground); border-color: var(--input); }
:where(input, textarea)::placeholder { color: var(--muted-foreground); opacity: 1; }
:where(button, input, textarea, select, a):focus-visible { outline: 2px solid var(--ring); outline-offset: -2px; }
@media (hover: hover) { [data-mari-part="home-widget"]:hover { border-color: var(--primary); } }

